package Controlador;
import Conexion.Conexion; import Modelo.Cita; import Modelo.EventoClinico; import java.sql.*; import java.util.*;
public class DashboardEnfermeriaDAO {
 public Cita proximaCita(int usuario){String q="SELECT a.idAtencion,a.descripcion,a.estado,p.idPaciente,CONCAT(up.nombres,' ',up.apellidos),h.fecha,h.hora_inicial,h.hora_final FROM atencion a JOIN horarios h ON h.idHorarios=a.Horarios_idHorarios JOIN paciente p ON p.idPaciente=a.Paciente_idPaciente JOIN usuarios up ON up.idUsuarios=p.Usuarios_idUsuarios JOIN enfermeras e ON e.idenfermeras=a.enfermeras_idenfermeras WHERE e.Usuarios_idUsuarios=? AND a.estado<>'Cancelada' AND TIMESTAMP(h.fecha,h.hora_inicial)>=NOW() ORDER BY h.fecha,h.hora_inicial LIMIT 1";try(Connection c=new Conexion().getConexion();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,usuario);try(ResultSet r=p.executeQuery()){if(r.next()){Cita x=new Cita();x.setIdCita(r.getInt(1));x.setTipo(r.getString(2));x.setEstado(r.getString(3));x.setPacienteId(r.getInt(4));x.setPacienteNombre(r.getString(5));x.setFecha(r.getDate(6));x.setHoraInicio(r.getTime(7));x.setHoraFin(r.getTime(8));return x;}}}catch(SQLException e){}return null;}
 public int pendientes(){return contar("SELECT COUNT(*) FROM paciente WHERE diagnostico IS NULL OR diagnostico='' OR diagnostico='Pendiente de completar'");} public int stockBajo(){return contar("SELECT COUNT(*) FROM medicamento WHERE existencias<=10");} public int activos(){return contar("SELECT COUNT(*) FROM tratamiento WHERE estado='Activo'");} public int finalizados(){return contar("SELECT COUNT(*) FROM tratamiento WHERE estado='Finalizado'");}
 private int contar(String q){try(Connection c=new Conexion().getConexion();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}catch(SQLException e){return 0;}}
 public List<EventoClinico> actividad(){List<EventoClinico> l=new ArrayList<>();String q="SELECT * FROM (SELECT h.fecha fecha,h.tipo tipo,h.descripcion descripcion FROM historial_clinico h UNION ALL SELECT b.fecha_hora fecha,'Nota de enfermería' tipo,b.nota descripcion FROM bitacora_enfermeria b UNION ALL SELECT s.fecha_hora fecha,'Signos vitales' tipo,CONCAT('Presión: ',COALESCE(s.presion_arterial,'—')) descripcion FROM signos_vitales s) x ORDER BY fecha DESC LIMIT 4";try(Connection c=new Conexion().getConexion();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next()){EventoClinico e=new EventoClinico();e.fecha=r.getTimestamp(1);e.tipo=r.getString(2);e.descripcion=r.getString(3);l.add(e);}}catch(SQLException e){}return l;}
}
